import{fileURLToPath}from'node:url';import{mkdir,writeFile,readFile}from'node:fs/promises';const{chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');
const out=fileURLToPath(new URL('../../docs/qa/product-2026-11-17',import.meta.url));await mkdir(out+'/scenarios',{recursive:true});
const b=await chromium.launch({executablePath:process.env.MX_CHROME_PATH||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--mute-audio']});const result=[];
try{const p=await b.newPage({viewport:{width:1100,height:1100},isMobile:true,hasTouch:true,deviceScaleFactor:1});let errors=[];p.on('pageerror',e=>errors.push(e.message));await p.route('**/*',route=>{const u=new URL(route.request().url());if(['127.0.0.1','localhost'].includes(u.hostname)||['data:','blob:'].includes(u.protocol))return route.continue();errors.push('外部请求被禁止: '+u.origin);return route.abort();});
await p.goto('http://127.0.0.1:5173/tests/fixtures/layout-audit.html');await p.locator('#audit-stage[data-ready=true]').waitFor();let scenarios=await p.locator('[aria-label=scene] option').evaluateAll(xs=>xs.map(x=>({id:x.value,label:x.textContent})));
if(process.env.AUDIT_SCENES)scenarios=scenarios.filter(s=>process.env.AUDIT_SCENES.split(',').includes(s.id));
if(!process.env.AUDIT_SCENES)await writeFile(out+'/scenario-catalog.json',JSON.stringify(scenarios,null,2));
const expect={'raise':'.mx-raise-editor','report':'.mx-report-overlay','history':'.mx-history-overlay','profile':'.mx-player-info-overlay','settings':'.mx-personal-settings','chat':'.mx-chat-dialog','insurance-single':'.mx-insurance','insurance-multi':'.mx-insurance','insurance-force':'.mx-insurance','second-board':'.mx-second-pcs','bring-wallet':'.mx-buyin-overlay','bring-score':'.mx-buyin-overlay','bring-diamond':'.mx-buyin-overlay','bring-insufficient':'.mx-buyin-overlay','media-video':'.mx-avatar-video','media-voice':'.mx-avatar-mic'};
for(const layout of(process.argv[2]?process.argv.slice(2):['original','balanced','oval','classic']))for(const s of scenarios){errors=[];await p.goto('http://127.0.0.1:5173/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout,scene:s.id,width:440,height:layout==='original'?952:782}),{waitUntil:'domcontentloaded'});await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:20000});await p.evaluate(async()=>{await document.fonts.ready;const root=document.querySelector('#audit-stage');const urls=new Set([...root.querySelectorAll('*')].filter(e=>e.checkVisibility()).flatMap(e=>[...getComputedStyle(e).backgroundImage.matchAll(/url\("?([^")]+)"?\)/g)].map(m=>m[1])));await Promise.all([...urls].map(url=>{const img=new Image();img.src=url;return img.decode().catch(()=>{});}));await Promise.race([Promise.all([...root.querySelectorAll('img')].filter(i=>i.checkVisibility()&&i.currentSrc).map(i=>i.decode().catch(()=>{}))),new Promise(r=>setTimeout(r,1500))]);});const phase=await p.locator('#audit-stage').getAttribute('data-phase');const text=await p.locator('#audit-stage').innerText();await p.locator('#audit-stage').screenshot({path:`${out}/scenarios/${layout}-${s.id}.jpg`,type:'jpeg',quality:82});const panels=await p.locator('#audit-stage').evaluate(root=>[...root.querySelectorAll('[role=dialog],section, .mx-insurance,.mx-second-pcs')].filter(e=>e.getBoundingClientRect().width&&e.getClientRects().length).map(e=>({class:e.className,text:e.textContent.slice(0,120)})));result.push({layout,...s,phase,errors:[...errors],panels,text});console.log(layout,s.id,phase,errors.length?JSON.stringify(errors):'');}
const resultFile=out+`/scenario-results-${process.env.AUDIT_SCENES?'refresh':process.argv[2]??'all'}.json`;let previous=[];if(process.env.AUDIT_SCENES)try{previous=JSON.parse(await readFile(resultFile,'utf8'));}catch{}const refreshed=new Set(result.map(r=>r.layout+':'+r.id));await writeFile(resultFile,JSON.stringify([...previous.filter(r=>!refreshed.has(r.layout+':'+r.id)),...result],null,2));}finally{await b.close();}
